// Exact production headers are frozen by build_probe.py. The only production
// difference is input-history residue banking. FFT/IR geometry stays identical. No special SIMD,
// floating-point flags, worker, profile instrumentation or gate is introduced.
#define spectralforge spectralforge_reference
#include "reference/ModeledCabConvolution.h"
#undef spectralforge
#define spectralforge spectralforge_residue_bank
#include "candidate/ModeledCabConvolution.h"
#undef spectralforge

namespace {
using Reference = spectralforge_reference::ModeledCabConvolution;
using Candidate = spectralforge_residue_bank::ModeledCabConvolution;
using Clock = std::chrono::steady_clock;
constexpr int warmCallbacks = 512;
constexpr int measuredCallbacks = 1600;
constexpr int inputPatternSize = 4096;
constexpr std::array<char, 8> order{{'A', 'B', 'B', 'A', 'B', 'A', 'A', 'B'}};
volatile double observableChecksum = 0.;

struct Configuration {
    int rate, block, channels, kernels;
    int responses() const { return kernels / 3; }
    std::string name() const {
        return std::to_string(rate) + "-" + std::to_string(block) + "-"
            + std::to_string(channels) + "-" + std::to_string(kernels);
    }
};

std::uint32_t nextRandom(std::uint32_t& state) {
    state ^= state << 13; state ^= state >> 17; state ^= state << 5;
    return state;
}

std::vector<juce::AudioBuffer<float>> makeResponses(const Configuration& c) {
    // The full 85 ms authored interval remains present, including its last tap.
    const int length = int(std::ceil(double(c.rate) * .085));
    std::vector<juce::AudioBuffer<float>> result;
    result.reserve(size_t(c.responses()));
    for (int response = 0; response < c.responses(); ++response) {
        result.emplace_back(1, length);
        std::uint32_t random = 0xa04c742bu + std::uint32_t(response) * 0x10203041u;
        for (int sample = 0; sample < length; ++sample) {
            const double noise = double(nextRandom(random) >> 8) / 16777216. - .5;
            const double carrier = std::sin(double(sample) * (.047 + response * .013));
            result.back().setSample(0, sample, float((.024 * noise + .002 * carrier)
                * std::exp(-5. * double(sample) / double(length))));
        }
        result.back().addSample(0, 3 + response * 7, .45f - .03f * float(response));
        result.back().addSample(0, length - 1, .001f * float(response + 1));
    }
    return result;
}

std::array<float, inputPatternSize> makeInput() {
    std::array<float, inputPatternSize> result{};
    std::uint32_t random = 0x73402ab9u;
    for (auto& sample : result)
        sample = float(double(nextRandom(random) >> 8) / 16777216. - .5) * .25f;
    return result;
}

template <class Engine> struct KernelGroup {
    using Prepared = typename Engine::Prepared;
    Configuration config;
    std::vector<std::shared_ptr<const Prepared>> prepared;
    std::vector<std::unique_ptr<Engine>> engines;
    std::vector<juce::AudioBuffer<float>> buffers;
    KernelGroup(const Configuration& c, const std::vector<juce::AudioBuffer<float>>& responses)
        : config(c) {
        for (const auto& response : responses)
            prepared.emplace_back(std::make_shared<const Prepared>(response, c.block, c.channels == 1));
        buffers.reserve(size_t(c.kernels));
        for (int i = 0; i < c.kernels; ++i) {
            engines.emplace_back(std::make_unique<Engine>(prepared[size_t(i % c.responses())]));
            buffers.emplace_back(c.channels, c.block);
        }
    }
    void reset() { for (auto& engine : engines) engine->reset(); }
    void fill(const std::array<float, inputPatternSize>& input, int callback) {
        for (int kernel = 0; kernel < config.kernels; ++kernel)
            for (int channel = 0; channel < config.channels; ++channel) {
                const int offset = (callback * config.block + kernel * 193 + channel * 911)
                    & (inputPatternSize - 1);
                const int first = std::min(config.block, inputPatternSize - offset);
                auto* destination = buffers[size_t(kernel)].getWritePointer(channel);
                std::memcpy(destination, input.data() + offset, size_t(first) * sizeof(float));
                if (first < config.block)
                    std::memcpy(destination + first, input.data(), size_t(config.block - first) * sizeof(float));
            }
    }
    void process() {
        for (int i = 0; i < config.kernels; ++i) engines[size_t(i)]->process(buffers[size_t(i)]);
    }
    bool consume(double& checksum, std::uint64_t& hash) const {
        bool finite = true;
        // All output checking is outside the timed interval. Both variants use
        // the same input sequence and consume every output sample.
        for (const auto& buffer : buffers)
            for (int channel = 0; channel < config.channels; ++channel)
                for (int sample = 0; sample < config.block; ++sample) {
                    const float value = buffer.getSample(channel, sample);
                    if (!std::isfinite(value)) finite = false;
                    checksum += double(value);
                    std::uint32_t bits = 0;
                    std::memcpy(&bits, &value, sizeof(bits));
                    hash ^= bits; hash *= 1099511628211ull;
                }
        return finite;
    }
};

struct Batch {
    std::array<std::int64_t, measuredCallbacks> nanoseconds{};
    double checksum = 0.;
    std::uint64_t outputHash = 14695981039346656037ull;
    bool finiteOutput = true;
};

template <class Engine> Batch runBatch(KernelGroup<Engine>& group,
                                      const std::array<float, inputPatternSize>& input) {
    group.reset();
    for (int callback = 0; callback < warmCallbacks; ++callback) {
        group.fill(input, callback); group.process();
    }
    Batch result;
    for (int callback = 0; callback < measuredCallbacks; ++callback) {
        group.fill(input, callback + warmCallbacks);
        const auto start = Clock::now();
        group.process();
        const auto end = Clock::now();
        result.nanoseconds[size_t(callback)] = std::chrono::duration_cast<std::chrono::nanoseconds>(end - start).count();
        result.finiteOutput = group.consume(result.checksum, result.outputHash) && result.finiteOutput;
    }
    observableChecksum = result.checksum;
    return result;
}

template <class Engine> void recordGeometry(std::ofstream& stream, const Configuration& c,
                                           char variant, const KernelGroup<Engine>& group) {
    const auto& p = *group.prepared.front();
    stream << c.name() << ',' << variant << ',' << c.rate << ',' << c.block << ',' << c.channels
        << ',' << c.kernels << ',' << c.responses() << ',' << p.fftSize << ',' << p.segmentSize
        << ',' << p.segments << ',' << p.bins << ',' << p.inputSegments
        << ',' << size_t(p.inputSegments) * size_t(2 * p.bins) * sizeof(float) * size_t(c.kernels)
        << ',' << p.impulseSpectra.size() * sizeof(float) * size_t(c.responses()) << '\n';
}
}

int main(int argc, char** argv) {
    try {
        if (argc != 2) throw std::runtime_error("Expected one new output-directory argument");
        const std::filesystem::path output(argv[1]);
        if (std::filesystem::exists(output) && !std::filesystem::is_empty(output))
            throw std::runtime_error("Output directory must be new or empty; reruns cannot overwrite evidence");
        std::filesystem::create_directories(output);
        std::ofstream summary(output / "batches.csv"), geometry(output / "geometry.csv");
        summary.exceptions(std::ios::badbit | std::ios::failbit);
        geometry.exceptions(std::ios::badbit | std::ios::failbit);
        summary << "case,rate,block,channels,kernels,responses,batch,variant,warm_callbacks,measured_callbacks,p50_us,p99_us,max_us,mean_us,checksum,output_hash,finite_output\n";
        geometry << "case,variant,rate,block,channels,kernels,responses,fft_size,segment_size,partitions,bins,input_segments,private_ring_bytes,shared_ir_bytes\n";
        summary << std::setprecision(17);
        const juce::ScopedNoDenormals noDenormals;
        const auto input = makeInput();
        int cases = 0, batches = 0;
        for (int rate : {48000, 96000}) for (int block : {32, 64, 128, 256})
            for (int channels : {1, 2}) for (int kernels : {6, 9}) {
                const Configuration config{rate, block, channels, kernels};
                const auto responses = makeResponses(config);
                KernelGroup<Reference> reference(config, responses);
                KernelGroup<Candidate> candidate(config, responses);
                recordGeometry(geometry, config, 'A', reference);
                recordGeometry(geometry, config, 'B', candidate);
                geometry.flush();
                std::array<std::uint64_t, 2> hashes{};
                std::array<bool, 2> seen{};
                for (size_t batch = 0; batch < order.size(); ++batch) {
                    const char variant = order[batch];
                    const auto result = variant == 'A' ? runBatch(reference, input) : runBatch(candidate, input);
                    const auto variantIndex = size_t(variant == 'B');
                    auto sorted = result.nanoseconds;
                    std::sort(sorted.begin(), sorted.end());
                    double mean = 0.;
                    for (auto sample : result.nanoseconds) mean += double(sample) / (1000. * measuredCallbacks);
                    const double p50 = double(sorted[800]) / 1000.;
                    const double p99 = double(sorted[1584]) / 1000.;
                    const double maximum = double(sorted.back()) / 1000.;
                    // Write only after all measurements in this batch finish.
                    std::ofstream raw(output / (config.name() + "-" + std::to_string(batch + 1) + "-" + variant + ".csv"));
                    raw.exceptions(std::ios::badbit | std::ios::failbit);
                    raw << "case,batch,variant,callback_index,wall_ns\n";
                    for (int callback = 0; callback < measuredCallbacks; ++callback)
                        raw << config.name() << ',' << batch + 1 << ',' << variant << ',' << callback
                            << ',' << result.nanoseconds[size_t(callback)] << '\n';
                    raw.close();
                    summary << config.name() << ',' << rate << ',' << block << ',' << channels << ',' << kernels
                        << ',' << config.responses() << ',' << batch + 1 << ',' << variant << ',' << warmCallbacks
                        << ',' << measuredCallbacks << ',' << p50 << ',' << p99 << ',' << maximum << ',' << mean
                        << ',' << result.checksum << ',' << result.outputHash << ',' << int(result.finiteOutput) << '\n';
                    summary.flush(); ++batches;
                    // Preserve the complete batch before reporting a correctness failure.
                    if (!result.finiteOutput) throw std::runtime_error("Non-finite kernel output");
                    if (seen[variantIndex] && hashes[variantIndex] != result.outputHash)
                        throw std::runtime_error("Repeated identical workload produced a different output hash");
                    hashes[variantIndex] = result.outputHash; seen[variantIndex] = true;
                    if (seen[0] && seen[1] && hashes[0] != hashes[1])
                        throw std::runtime_error("Residue banking changed the output hash");
                }
                ++cases;
                std::cout << "CASE_COMPLETE case=" << config.name() << " batches=8 callbacks=12800" << std::endl;
            }
        std::cout << "PROBE_COMPLETE cases=" << cases << " batches=" << batches
            << " callbacks=" << batches * measuredCallbacks << " warm_callbacks=" << batches * warmCallbacks
            << " order=ABBABAAB all_output_hashes=matched diagnostic_only=1" << std::endl;
        return cases == 32 && batches == 256 ? 0 : 1;
    } catch (const std::exception& error) {
        std::cerr << "PROBE_FAILED " << error.what() << std::endl;
        return 1;
    }
}
